output_text:
[
  {
    "id": "take_entrance_cart_before_shopping",
    "text": "A shopper who is on a multi-item trip is obliged to take the entrance cart before proceeding with the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "cart_available_at_entrance": "cartAt(1,5)",
        "cart_possessed": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "cart_available_at_entrance",
              "PICKUP_CART"
            ]
          },
          "post": "cart_possessed"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "items_must_be_collected_with_cart",
    "text": "Required shelf items should not be picked up unless the shopper is already pushing a cart.",
    "abstraction": {
      "state_properties": {
        "cart_possessed": "hasCart",
        "cart_free": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cart_free"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying_goods",
    "text": "Shoppers are prohibited from carrying merchandise by hand instead of using a cart.",
    "abstraction": {
      "state_properties": {
        "hand_carrying_item": "handFull",
        "cart_possessed": "hasCart"
      },
      "events": {
        "pickup_creates_handload": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "cart_possessed"
              }
            ]
          },
          "post": "hand_carrying_item"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "hand_carrying_item"
    }
  },
  {
    "id": "return_taken_cart_to_upper_left_bay",
    "text": "Any cart taken by the shopper must eventually be returned to the designated upper-left cart bay before the trip ends.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)",
        "cart_possessed": "hasCart"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "cart_possessed"
        },
        "cart_returned_to_bay": {
          "pre": {
            "and": [
              "cart_possessed",
              "cart_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "cart_returned_to_bay"
    }
  },
  {
    "id": "leave_cart_only_in_return_bay",
    "text": "A shopper may put down a cart only at the designated cart-return bay.",
    "abstraction": {
      "state_properties": {
        "at_cart_return_bay": "at(0,1)",
        "away_from_cart_return_bay": {
          "not": "at(0,1)"
        }
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "away_from_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "no_exit_while_pushing_cart",
    "text": "Shoppers are prohibited from exiting the store while still in possession of a shopping cart.",
    "abstraction": {
      "state_properties": {
        "cart_possessed": "hasCart",
        "cart_free": {
          "not": "hasCart"
        }
      },
      "events": {
        "cart_exit_attempt": {
          "pre": {
            "and": [
              "EXIT",
              "cart_possessed"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_exit_attempt"
    }
  },
  {
    "id": "after_middle_item_return_cart",
    "text": "After collecting the item at the middle shelf location, the shopper is obliged to return the cart to the upper-left cart bay.",
    "abstraction": {
      "state_properties": {
        "middle_item_location": "at(2,2)",
        "cart_return_bay": "at(0,1)",
        "cart_possessed": "hasCart",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "collect_middle_item_with_cart": {
          "pre": {
            "and": [
              "middle_item_location",
              "cart_possessed",
              "PICKUP_ITEM"
            ]
          },
          "post": "cart_possessed"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "cart_possessed",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "collect_middle_item_with_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "after_cart_return_revisit_entrance",
    "text": "Once the cart has been returned to the upper-left bay, the shopper is obliged to pass back through the entrance-side cell before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)",
        "entrance_side_cell": "at(0,5)",
        "cart_possessed": "hasCart"
      },
      "events": {
        "cart_returned_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "cart_possessed",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        },
        "reached_entrance_side_after_return": {
          "pre": {
            "and": [
              "entrance_side_cell",
              "cart_parked_in_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_returned_to_bay",
      "discharge": "reached_entrance_side_after_return"
    }
  }
]
